<script setup>
import {ref,computed,onMounted} from 'vue';
const windows=ref([]),screens=ref([]),chosen=ref([]),screen=ref(''),busy=ref(false),error=ref(''),message=ref(''),preview=ref(null),profiles=ref({});
const settings=ref({width:960,height:540,columns:3,gap:8,padding:8,aspect:true,mode:'网格排列'});
try{const saved=JSON.parse(localStorage.getItem('running-window-settings')||'null');if(saved)Object.assign(settings.value,saved)}catch{}
const selected=computed(()=>windows.value.filter(w=>chosen.value.includes(w.id)));
async function call(action,payload={}){const r=await window.pywebview.api.running_windows(action,payload);if(!r.ok)throw Error(r.error);return r.data}
function payload(){return {windows:selected.value,screen:screen.value,settings:settings.value,profiles:profiles.value}}
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{const old=new Set(windows.value.map(w=>w.id));const r=await call('list');windows.value=r.windows;screens.value=r.screens;chosen.value=r.windows.filter(w=>!old.has(w.id)||chosen.value.includes(w.id)).map(w=>w.id);if(!screens.value.some(s=>s.id===screen.value))screen.value=screens.value[0]?.id||'';profiles.value={};settings.value.mode=settings.value.mode==='自定义坐标'?'网格排列':settings.value.mode;await updatePreview()}catch(e){error.value=e.message}finally{busy.value=false}}
let previewRequest=0;
async function updatePreview(){const request=++previewRequest;preview.value=null;error.value='';if(!selected.value.length)return;try{const result=await call('preview',payload());if(request!==previewRequest)return;preview.value=result;localStorage.setItem('running-window-settings',JSON.stringify(settings.value))}catch(e){error.value=e.message}}
async function apply(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{const r=await call('apply',payload());const failed=r.results.filter(x=>!x.ok);message.value=`已排列 ${r.results.length-failed.length} 个窗口`+(failed.length?`，${failed.length} 个失败`:'');if(failed.length)error.value=failed.map(x=>x.error).join('；')}catch(e){error.value=e.message}finally{busy.value=false}}
async function focus(w){try{await call('focus',{windows:[w]})}catch(e){error.value=e.message}}
function toggleAll(){chosen.value=chosen.value.length===windows.value.length?[]:windows.value.map(w=>w.id);updatePreview()}
function rectStyle(r){const [x,y,w,h]=preview.value.work;return {left:(r[0]-x)/w*100+'%',top:(r[1]-y)/h*100+'%',width:r[2]/w*100+'%',height:r[3]/h*100+'%'}}
let drag=null;
function press(e,id){if(busy.value||e.button!==0)return;const stage=e.currentTarget.parentElement;drag={id,startX:e.clientX,startY:e.clientY,rect:[...preview.value.rects[id]],bounds:stage.getBoundingClientRect(),moved:false};e.currentTarget.setPointerCapture(e.pointerId)}
function move(e){if(!drag)return;const p=preview.value,work=p.work;let dx=(e.clientX-drag.startX)*work[2]/drag.bounds.width,dy=(e.clientY-drag.startY)*work[3]/drag.bounds.height;if(Math.abs(dx)+Math.abs(dy)<3&&!drag.moved)return;drag.moved=true;const r=drag.rect;p.rects[drag.id]=[Math.round(Math.max(work[0],Math.min(work[0]+work[2]-r[2],r[0]+dx))),Math.round(Math.max(work[1],Math.min(work[1]+work[3]-r[3],r[1]+dy))),r[2],r[3]]}
async function release(){if(!drag)return;const moved=drag.moved;drag=null;if(!moved)return;settings.value.mode='自定义坐标';const frame=preview.value.frame||[0,0];profiles.value=Object.fromEntries(Object.entries(preview.value.rects).map(([id,r])=>[id,{x:r[0],y:r[1],width:r[2]-frame[0],height:r[3]-frame[1]}]));await updatePreview()}
onMounted(refresh);
</script>
<template><section class="running-page"><header><div><h1>运行窗口</h1><p>管理当前打开的阴阳师窗口，不限启动来源或方案。</p></div><button @click="refresh" :disabled="busy">刷新窗口</button></header><p v-if="error" class="run-error" role="alert">{{error}}</p><p v-if="message" role="status">{{message}}</p><div class="running-grid"><aside><div class="run-list-title"><b>{{windows.length}} 个窗口</b><button @click="toggleAll" :disabled="busy">{{chosen.length===windows.length?'取消全选':'全选'}}</button></div><div class="run-list"><label v-for="w in windows" :key="w.id" @dblclick="focus(w)"><input type="checkbox" v-model="chosen" :value="w.id" @change="updatePreview" :disabled="busy"><span><strong>{{w.title}}</strong><small>{{w.rect[2]}} × {{w.rect[3]}} · 双击定位</small></span><button @click.prevent="focus(w)" :disabled="busy" title="定位游戏窗口">↗</button></label><p v-if="!windows.length">暂无已打开的游戏窗口。</p></div></aside><article><div class="run-options"><label>目标屏幕<select v-model="screen" @change="updatePreview" :disabled="busy"><option v-for="(s,i) in screens" :value="s.id">{{i+1}} · {{s.work[2]}} × {{s.work[3]}}{{s.primary?' · 主屏幕':''}}</option></select></label><label>排列方式<select v-model="settings.mode" @change="profiles={};updatePreview()" :disabled="busy"><option>网格排列</option><option>错落排列</option><option>自定义坐标</option></select></label><label>画面宽度<input type="number" v-model.number="settings.width" @change="settings.aspect&&(settings.height=Math.round(settings.width*9/16));profiles={};updatePreview()" :disabled="busy"></label><label>画面高度<input type="number" v-model.number="settings.height" @change="profiles={};updatePreview()" :disabled="busy||settings.aspect"></label><label>列数<input type="number" v-model.number="settings.columns" @change="updatePreview" :disabled="busy"></label><label>窗口间距<input type="number" v-model.number="settings.gap" @change="updatePreview" :disabled="busy"></label><label>四周留白<input type="number" v-model.number="settings.padding" @change="updatePreview" :disabled="busy"></label><label class="run-aspect"><input type="checkbox" v-model="settings.aspect" @change="settings.aspect&&(settings.height=Math.round(settings.width*9/16));profiles={};updatePreview()" :disabled="busy">锁定 16:9</label></div><div class="run-preview-area"><div class="run-stage" v-if="preview" :style="{aspectRatio:preview.work[2]+'/'+preview.work[3]}"><div v-for="(r,id,i) in preview.rects" :key="id" class="run-window" :style="rectStyle(r)" @pointerdown="press($event,id)" @pointermove="move" @pointerup="release" @pointercancel="release" :title="windows.find(w=>w.id===id)?.title"><b>{{i+1}} {{windows.find(w=>w.id===id)?.title}}</b><small>{{r[2]}} × {{r[3]}}</small></div></div><p v-else class="run-empty">{{busy?'正在加载窗口…':'选择窗口后显示排列预览'}}</p></div><footer><span>已选 {{selected.length}} 个 · 拖动调整位置，应用后移动真实窗口。</span><button class="run-apply" @click="apply" :disabled="busy||!preview||!selected.length">{{busy?'正在处理…':'应用排列'}}</button></footer></article></div></section></template>
<style scoped>
.running-page{height:100%;display:flex;flex-direction:column;min-height:0;color:#332e28}.running-page header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.running-page h1{font-size:24px;margin:0 0 8px}.running-page p{color:#867665;margin:0}.running-page button,.running-page select,.running-page input[type=number]{border:1px solid #dcccb8;background:#fffaf3;color:#604c38;border-radius:5px;padding:8px;font:inherit}.running-page button{cursor:pointer}.running-page button:disabled{opacity:.5;cursor:default}.running-grid{display:grid;grid-template-columns:290px minmax(0,1fr);gap:18px;flex:1;min-height:0}.running-grid aside,.running-grid article{border:1px solid #e2d6c5;border-radius:9px;background:#fffcf7;min-height:0;display:flex;flex-direction:column;overflow:hidden}.run-list-title{display:flex;align-items:center;justify-content:space-between;padding:14px;border-bottom:1px solid #eadfce}.run-list{overflow:auto;padding:8px}.run-list label{display:flex;align-items:center;gap:9px;padding:12px 5px;border-bottom:1px solid #eee4d7}.run-list span{flex:1;min-width:0}.run-list strong{display:block;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.run-list small{display:block;color:#94816b;font-size:12px;margin-top:6px}.run-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:18px}.run-options label{font-size:12px;color:#85725d;min-width:0}.run-options label>*{display:block;width:100%;box-sizing:border-box;margin-top:6px}.run-options .run-aspect{display:flex;align-items:center;gap:6px}.run-aspect input{width:auto;margin:0}.run-preview-area{flex:1;min-height:0;padding:18px;background:#eee8de;display:flex;align-items:center;justify-content:center;overflow:auto}.run-stage{width:100%;position:relative;max-height:100%;background:#252f39;border:1px solid #a18e73;border-radius:5px;overflow:hidden}.run-window{position:absolute;box-sizing:border-box;background:#52636be6;border:1px solid #d3b58c;color:#fff4e2;overflow:hidden;cursor:grab;touch-action:none;padding:6px;user-select:none}.run-window b{font-size:12px;white-space:nowrap;display:block;overflow:hidden;text-overflow:ellipsis}.run-window small{font-size:10px;opacity:.7}.running-page footer{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:15px;font-size:12px;color:#8b7863}.running-page .run-apply{background:#795c41;color:white;padding:10px 22px}.running-page .run-error{color:#aa4634;margin-bottom:10px}@media(max-width:1150px){.running-grid{grid-template-columns:240px minmax(0,1fr)}.run-options{grid-template-columns:repeat(3,minmax(0,1fr))}}
</style>
